#### 做法1：维护滑动窗口

首先可以发现操作次数与选择无关，因此从右到左贪心选择：

```cpp
ll sum = 0, ans = 0;

for (int i = n; i >= 1; i--) {
    dp[i] = (a[i] + sum) % 2;
    ans = (ans + dp[i]) % 2;

    sum = (sum + dp[i]) % 2;  // 加入 dp[i]
    if (i + k <= n)
        sum = (sum - dp[i + k] + 2) % 2; // 移出 dp[i+k]
}
```


#### 做法2：找特殊位置


```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    int t;
    cin >> t;
    for (int tc = 0; tc < t; tc++) {
        int n, k;
        cin >> n >> k;
        long long sum = 0;
        for (int i = 0; i < n; i++) {
            long long a;
            cin >> a;
            if (i % (k + 1) == 0)
                sum += a;
        }
        cout << (sum % 2 ? "Alice" : "Bob") << endl;
    }
}
```

签到。可以发现 Menji 必胜的情况是，数组由两两相同的数字组成的数对、以及这些数字的异或和，与一个其他数字组成：

$$ [a, a, b, b, c, c, …, g, g, x, y] , x = a \oplus b … \oplus g $$

（写得不太严谨，总之差不多就是这么个意思）

- Menji 必胜的策略是：先取走数对的异或和，之后， Bot 要么取走无关的数 $ y $，要么拆掉任意一个数对，Menji只需要在 Bot 拆掉数对使跟随 Bot 选择一样的数即可，可以保证 Menji 每个数对都能取到一个数，从而消去第一步选择的异或和。

```cpp
void solve() {
		int n;
		cin >> n;
		vector<int> a(n * 2);
		
		ll ans = 0;
		
		map<int, int> mp, mpb;
		
		
		for(int i = 0; i < n * 2; i++){
			int x; cin >> x;
			mp[x]++;
		}
		
		for(auto [x, y] : mp){
			if(y % 4 == 0) continue; //四个相同的数字，Menji能保证取到两个，可自身异或为0，,忽略
			else if(y % 4 != 1) ans ^= x; // 自身无法异或为0的数对，需要依靠外在的异或和消除

			if(y % 2) mpb[x] = 1; //落单的数字可能是异或和的备选，记录
		}
		
		if(mpb.size() == 0 && ans == 0) cout << "Menji\n";  
		else if (mpb.size() == 2 && mpb[ans] != 0) cout << "Menji\n"; //除了数对以外的数，其中有一个是数对的异或和
		else cout << "Bot\n";
}
```

> 您将得到一棵具有 $n$ 个顶点的树，编号从 $1$ 到 $n$ 。最初，所有顶点都是白色的。必须选择一个介于 $1$ 和 $2n$ 之间的整数 $k$ 。然后，对于按递增顺序从 $1$ 到 $n$ 的每个 $i$ ，如果树包含编号为 $k-i$ 和 $k-i \ne i$ 的顶点，执行以下操作:

限制讨论范围到特殊解；是否经过一个特定路径可以依靠bfs判联通块

> 1. 无论顶点 $i$ 和 $k-i$ 的当前颜色如何，它们都将被重新着色为黑色

> 2. $i$ 和 $k-i$ 之间的简单路径上的所有白色顶点都重新着色为灰色。此路径上其他顶点的颜色不会更改。

> 必须选择 $k$ 以最大化黑色顶点的数量（较高优先级）以及灰色顶点的数量（较低优先级）。换句话说，选择 $k$ 以使树中黑色顶点的数量尽可能大，并且在给出最大数量的黑色顶点的 $k$ 的值中，选择给出尽可能多的灰色顶点的值。找出 $k$ 的任意最优值。如果 $k$ 有多个合适的值，则打印其中的任何一个。

- 黑点限制条件将答案限制在，偶数只能输出n，奇数只能在n，n+1，n+2中选，
- 这样灰点条件的判定就只需要验证三种答案中，哪一种答案中唯一一个未被涂黑的点可以被涂黑，
- 对其中的两种情况，删除想判断的点之后再跑bfs联通块，再验证每个起终点是否在同一个联通快，
- 如果不是，就代表二者的路径必经过被删点，输出答案；
- 否则，输出没被验证情况的答案（已验证的情况不会更优）


```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef unsigned long long ull;
const ll N = 3e5 + 10, M = 1e5+10;
const ll mod = 676767677;


void solve(){
	int n;
	cin >> n;
//	vector<int> g[N]; 爆T写法，lca和树剖都能卡过的2s，这个直接TLE on 2
	vector<vector<int>> g(n + 1); // 343ms
	
	for(int i = 1; i < n; i++){
		int u, v;
		cin >> u >> v;
		g[u].push_back(v);
		g[v].push_back(u);
	}
	
	if(n % 2 == 0){
		cout << n + 1 << "\n";
		return;
	}
	
	int ans = n;
	for(auto k : {n + 1, n + 2}){
		int del = k == n + 1 ? (n + 1) / 2 : 1;
	
		
		vector<int> belong(n + 1);
		int cnt = 0;
		queue<int> q;
		belong[del] = -1;
		
		for(int i = 1; i <= n; i++){
			if(belong[i]) continue;
			cnt++;
			q.push(i);
			while(!q.empty()){
				int u = q.front();
				q.pop();
				belong[u] = cnt;
				for(auto v : g[u]){
					if(!belong[v]) belong[v] = cnt, q.push(v);
				}
			}
		}
		
		
		for (int i = 1; i <= n; i++) {
			int j = k - i;
			if (j < 1 || j > n || i >= j) continue;
			
			if (belong[i] != belong[j]) {
				ans = max(ans, k);
				break;
			}
		}
	}
	
	cout << ans << "\n";
}

int main(){
	ios::sync_with_stdio(0);
	cin.tie(0), cout.tie(0);
	ll T; cin >> T;
	while(T--) solve();
	return 0;
}
```

> 把兔子分成若干组，给出任意两只兔子在一组的得分，求最大化得分的分组方案

子集划分：先构造子集数组val[mask]，代表mask中为1位置全连通的值，然后对每个mask枚举包含的子集val，和其补集val的和，相当于每个子集再枚举其一个两子集划分合并的和。


dp[mask] = max(dp[mask], dp[mask ^ subset] + val[subset] 

```cpp
#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
const int N = 2e5 + 10;


ll dp[1 << 16], val[1 << 16], g[16][16];
ll n;

int main(){
	ios::sync_with_stdio(false);
	cin.tie(0); cout.tie(0);
	
	cin >> n;
	
	for(int i = 0; i < n; i++){
		for(int j = 0; j < n; j++){
			cin >> g[i][j];
		}
	}
	// 预处理每个子集内不作划分的值
	for(int mask = 1; mask < (1 << n); mask++){
		int j = __builtin_ctz(mask);
		val[mask] = val[mask ^ (1 << j)];
		for(int i = 0; i < n; i++){
			if(mask & (1 << i)){
				val[mask] += g[i][j];
			}
		}
	}
	
    //枚举每个子集的划分
	for(int mask = 0; mask < (1 << n); mask++){
		for(int subset = mask; subset; subset = (subset - 1) & mask){
			dp[mask] = max(dp[mask], dp[mask ^ subset] + val[subset]);
		}
	}
	
	cout << dp[(1 << n) - 1] << endl;
}
```

> 对给定的数组 $ a ( a_i<16 )$ ， 可以对数组中的任意数字执行以下操作任意次数）：
> - 选择索引 $ 1≤i<n $  和整数 $ 1≤k≤5 $ ，然后将 $ a_i $ 和 $  a_i+1 $ 分别替换为 $ a_i⊕(3⋅k) $ 和 $ a_i+1⊕(3⋅k)  $
> 求出这样操作之后数组中可以被3整除的数的最大数量。



- 数字的范围很小，所以可以全部写出来然后手玩一下情况：
- 一个数与第 $ i $ 位为 $ 1 $ 的数异或，这个数的第 $ i $ 位会被翻转；
- 由于 $ 3, 6, 9, 12, 15 $ 的二进制表示都具有偶数个 $ 1 $ 位，所以会将另一个数二进制的偶数多个位置翻转。
- 可能被纳入答案的只有可能是 `popcount` 为偶数的数。
- 而对 `popcount` 为奇数的数进行异或不会改变它对答案无贡献的事实，对 `popcount` 为偶数的数进行大于0的任意多次异或都可以保持合法，所以每个`popcount` 为偶数的数都可以最终转变为3的倍数。
- 因此，维护`popcount` 为偶数的数的个数即为答案。

```cpp
#include <bits/stdc++.h>
using namespace std;
#define double long double //提升精度
typedef long long ll;
const int N = 5e5 + 10;
ll mod = 998244353;
ll inf = 1e18 + 10;


ll n, m;
ll ans = 0;

bool ok(int x){
	return (__builtin_popcount(x) % 2 == 0);
}

void solve(){
	int n, q;
	cin >> n >> q;
	int ans = 0;
	vector<int> v(n + 1);
	for(int i = 1; i <= n; i++) cin >> v[i], ans += ok(v[i]);
	
	cout << ans << " ";
	
	while(q--){
		int x, val;
		cin >> x >> val;
		ans += ok(val) - ok(v[x]);
		v[x] = val;
		cout << ans << " ";
	}
	cout << endl;
}

int main(){
	ios::sync_with_stdio(false);
	cin.tie(0); cout.tie(0);
	int T; cin >> T;
	while(T--) solve();
	return 0;
}
	
```

```cpp
#include <bits/stdc++.h>
using namespace std;
const int N = 1e5 + 10;
int n, m;
int h[2*N], e[2*N], ne[2*N],  idx;
int r, dn, dfn[N];
int cnt, low[N];
bool buc[N];

void add(int a, int b){
	e[idx] = b, ne[idx] = h[a], h[a] = idx++;
}

void dfs(int u){
	dfn[u] = low[u] = ++dn;
	int son = 0;
	for(int i = h[u]; i != -1; i = ne[i]){
		int v = e[i];
		if(!dfn[v]){
			son++, dfs(v), low[u] = min(low[u], low[v]);
		//定理2：v不能通过u以外的点到达
		if(low[v] >= dfn[u] && u != r) 	cnt += !buc[u], buc[u] = 1;//如果已经加过就不加了
		}
		else low[u] = min(low[u], dfn[v]);
	}
	if(son = = 2 && u == r) cnt += !buc[u], buc[u] = 1;//定理1：根结点特判
}


int main(){
	cin >> n >> m;
	memset(h, -1, sizeof h);
	for(int i = 1; i <= m; i++)
	{
		int u, v;
		cin >> u >> v;
		add(u, v), add(v, u);
	}
	//该连通分量没有访问过，dfs
	for(int i = 1; i <= n; i++) if(!dfn[i]) r = i, dfs(i);
	cout << cnt << endl;
	for(int i = 1; i <= n; i++) if(buc[i]) cout << i << ' ';
	return 0;
}
```

#### 法1：dfs

这题绿的原因应该是暴搜可过。。

从高位向低位，该位置为1或0代表着考虑当前数组的前半段还是后半段，如果是2则是前后两个半段相加，然后递归到数组长度为1为止。


```cpp
#include <bits/stdc++.h>
using namespace std;
#define double long double //提升精度
typedef long long ll;
const int N = 1 << 17;
ll mod = 998244353;
ll inf = 1e18 + 10;

ll n, m;
ll ans = 0;
int a[N];
int tmp[20][N];

void dfs(int depth, int len, int * a){
	if(len == 1){ans ^= a[0]; return;}//递归到数组长度为1，就是当前组合答案
	
	
	int mid = len >> 1;
	
	dfs(depth + 1, mid, a);//0：前半段
	dfs(depth + 1, mid, a + mid); //1：后半段
	
	
	int* merge = tmp[depth];
	
	for(int i = 0; i < mid; i++){
		merge[i] = a[i] + a[i + mid];
	}
	dfs(depth + 1, mid, merge);//2：相加之后
}

int main(){
	ios::sync_with_stdio(false);
	cin.tie(0); cout.tie(0);
	
	int n; cin >> n;
	
	for(int i = 0; i < (1 << n); i++) cin >> a[i];
	
	dfs(0, 1 << n, a);
	
	cout << ans << "\n";
	
	return 0;

}
	

```

#### 法2：

用一维数组来存储所有状态，这时候使用三进制可以用0、1、2来存储0、1、?的所有状态，然后用高维前缀和的想法更新即可。

```cpp
#include <bits/stdc++.h>
using namespace std;
#define double long double //提升精度
typedef long long ll;
const int N = 1e6 + 10;
ll mod = 998244353;
ll inf = 1e18 + 10;


ll n, m;
ll ans = 0;


int main(){
	ios::sync_with_stdio(false);
	cin.tie(0); cout.tie(0);
	
	int n; cin >> n;
	
	vector<ll> idx(17);
	
	idx[0] = 1;
	for(int i = 1; i <= 16; i++) idx[i] = idx[i-1] * 3;
	
	
	int m  = (1 << n);
	
	vector<ll> a(m), p(m), sum(idx[n]);
	
	for(int i = 0; i < m; i++) cin >> a[i];
	
	for(int i = 0; i < m; i++){
		int x = 0;
		for(int j = 0; j < n; j++){
			if((i >> j) & 1) x += idx[j];//填充三进制，此时只有0和1位是确定的
		}
		p[i] = x;
		sum[x] = a[i];
	}
	
	for(int i = 0; i < n; i++){ //枚举每一位
		for(int j = 0; j < idx[i]; j++){ // 三进制位都已经更新过的低位
			for(int k = 0; k < (1 << (n - i - 1)); k++){//还没处理过的高位，只有0和1位
				int x = p[k] * idx[i + 1] + j;//拼凑出当前需要更新的数，第i位为0
				sum[x + 2 * idx[i]] = sum[x] + sum[x + idx[i]];//第i位为2的值是第i位为1和第i位为0的加和
				//三进制的2位是该位为0和1的加和
			}
		}
	}
	
	
	for(int i = 0; i < idx[n]; i++){
		ans ^= sum[i];
	}
	
	cout << ans << "\n";
	return 0;
}
	
```

> 给定的是一个简单的无向图，在删除零条或更多条边后，请找出图中尽可能少的连通部分，以便每个联通块内的所有点之间都有直连边

同子集划分，注意初始化mask为0的状态，以及sub可以只枚举mask最低位为1的位来优化，不过复杂度还是在 $ O(3^n) $左右

- 目标是把所有顶点划分成若干合法的组
- 每一组是否合法，只取决于组内顶点集合
- 可以预处理每个集合是否构成团
- 剩余顶点仍然是同一个最小团划分问题


```cpp
#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
const int N = 2e5 + 10;


ll dp[1 << 18], val[1 << 18];
bool g[18][18];
ll n, m;

int main(){
	ios::sync_with_stdio(false);
	cin.tie(0); cout.tie(0);
	
	cin >> n >> m;
	
	for(int i = 0; i < n; i++) g[i][i] = 1;
	for(int i = 0; i < m; i++){
		int u, v;
		cin >> u >> v;
		u--, v--;
		g[u][v] = g[v][u] = 1;
	}
	
	val[0] = 1;//注意初始化0的情况！
	for(int mask = 1; mask < (1 << n); mask++){
        //每次加入最低位的点，观察联通性是否还存在
		int b = __builtin_ctz(mask);
		if(val[mask ^ (1 << b)]){
			bool flag = 0;
			for(int i = 0; i < n; i++){
				if((mask & (1 << i)) && !g[i][b]){
					flag = 1;
					break;
				}
			}
			if(!flag) val[mask] = 1;
		}
	}
	
	for(int mask = 1; mask < (1 << n); mask++){
		if(__builtin_popcount(mask) == 1) dp[mask] = 1;
		else dp[mask] = 0x3f3f3f3f;
		for(int sub = mask; sub; sub = (sub - 1) & mask){
			if(!(sub & (mask & -mask))) continue;
			//优化：只枚举包含 mask 最低位元素的子集
			if(dp[mask ^ sub] < 0x3f3f3f3f && val[sub]) dp[mask] = min(dp[mask], dp[mask ^ sub] + 1);
		}
	}
	
	cout << dp[(1 << n) - 1];
	
}
```

