> 从n道菜选m道来吃，即如果他在吃y菜之前正好吃了x菜（在x和y之间不能有其他菜），那么他的满意度就会提高c个单位。最大化满意度

加入点与已经加入的点有关的，可以通过 `dp[mask][last]` 将相关联的点分离出来，定义与该属性有关的状态，之后更新二维状态

内层是同时枚举last和新加入的点，\[
O(n^2 2^n)
\]，所以最坏情况下约为：
\[
18^2\times 2^{18}\approx 8.49\times10^7
\]

不过实际执行的转移远没有这么多，因为：
```cpp
if(!(mask & (1 << last))) continue;
if(mask & (1 << j)) continue;
```


对于一个有 \(k\) 个 1 的 mask，只有：
- \(k\) 种合法的 last
- \(n-k\) 种合法的 j
因此真正的有效转移次数为：
\[
\sum_{k=1}^{n-1}\binom nk k(n-k)
=n(n-1)2^{n-2}
\]



```cpp
#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
const int N = 18;
const ll mod = 1e9 + 7;


ll dp[1 << N][N], a[N];


ll n, m, k;
ll ans;



int main(){
	ios::sync_with_stdio(false);
	cin.tie(0); cout.tie(0);
	
	cin >> n >> m >> k;

	//注意初始化
	for(int i = 0; i < n; i++) cin >> a[i], dp[1 << i][i] = a[i];
	
	map<pair<int, int>, ll> mp;
	
	for(int i = 0; i < k; i++){
		int x, y, z;
		cin >> x >> y >> z;
		x--, y--;
		mp[{x, y}] = z;
	}

	for(int mask = 0; mask < (1 << n); mask++){
		int cnt = __builtin_popcount((unsigned)mask);
		
		if(cnt == m){//达到上限，停止转移
			for(int last = 0; last < n; last++){
				if(mask & (1 << last))
					ans = max(ans, dp[mask][last]);
			}
			continue;
		}
		
		for(int last = 0; last < n; last++){
			if(mask & (1 << last)){
				for(int j = 0; j < n; j++){
					if(!(mask & (1 << j))){
						dp[mask | (1 << j)][j] = max(dp[mask | (1 << j)][j], dp[mask][last] + a[j] + mp[{last, j}]);
					}
				}
			}
			
		}
	}
	
	cout << ans;
}
