> 不同位置放着一些物品，女孩站在起点处，每次只能携带一件或者两件物品放回原点。
> 找出行动顺序，使女孩能在最短时间内将所有物品取回原点。(1 ≤ n ≤ 24)。

注意题目范围可知是状压。由于每次都要从起点出发将物品取回原点，所以**取物品的顺序不重要**，只是需要规划物品是被单个还是成对取回、以及两两取回时的物品搭配即可。

因此，用mask记录已取回的物品，从0开始向上枚举，用当前最小未取物品自己或和其余未取物品的搭配不断向前更新状态即可。时间复杂度 $O(n·2^n)$.

由于本题需要输出最优路径，所以每次更新状态时要开一个数组记录当前状态的前驱状态。

```cpp
#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
const int N = 2e5 + 10;

int n, x[30], y[30], xs, ys;
int d0[30], d[30][30];
int dp[1 << 24], pre[1 << 24];


int main(){
	ios::sync_with_stdio(false);
	cin.tie(0); cout.tie(0);
		
	cin >> xs >> ys;
	cin >> n;
	
	for(int i = 0; i < n; i++) cin >> x[i] >> y[i];
	
	for(int i = 0; i < n; i++){
		d0[i] = (x[i] - xs) * (x[i] - xs) + (y[i] - ys) * (y[i]- ys);
		for(int j = i; j <= n; j++) d[i][j] = d[j][i] = (x[i] - x[j]) * (x[i] - x[j]) +  (y[i] - y[j]) * (y[i] - y[j]);
	}
	
	memset(dp, 0x3f, sizeof dp);
	dp[0] = 0;
	for(int mask = 0; mask < (1 << n) - 1; mask++){
		if(dp[mask] >= 0x3f3f3f3f) continue;
		int i = 0;
		while(mask >> i & 1) i++;// 最小的未取物品
		
		
		// 单独取 i
		int pos = mask | (1 << i);
		int dist = dp[mask] + 2 * d0[i];
		if(dist < dp[pos]) dp[pos] = dist, pre[pos] = mask;
		
		
		// 选取另一个j一起取
		for(int j = i + 1; j < n; j++){
			if(mask >> j & 1) continue;
			pos = mask | (1 << i) | (1 << j);
			dist = dp[mask] + d0[i] +d0[j] + d[i][j];
			if(dist < dp[pos]) dp[pos] = dist, pre[pos] = mask;			
		}
	}
	
	cout << dp[(1 << n) - 1] << "\n0 ";
	
	int cur = (1 << n) - 1;
	while(cur){
		int p = pre[cur];
		int diff = cur ^ p;
		for(int k = 0; k < n; k++){
			if(diff >> k & 1) cout << k + 1 << " ";
		}
		cout << 0 << " ";
		cur = p;
	}
	cout << "\n";
	return 0;
}
```

