void dfs(int u, int fa){
	dfn[u] = low[u] = ++tim; 
	
	for(auto [v, idx] : g[u]){
		if(idx == fa) continue;//只是跳过进入子节点的边，以处理重边的状况
		if(!dfn[v]){
			dfs(v, idx), low[u] = min(low[u], low[v]);
			if(low[v] > dfn[u]) isbridge[idx] = 1;
		}	
		else low[u] = min(low[u], dfn[v]);
	}
}

void get_ebcc(int s){
	queue<int> q;
	q.push(s);
	belong[s] = ++cnt;
	
	while(!q.empty()){
		int u = q.front();
		q.pop();
		
		for(auto [v, idx] : g[u]){
			if(isbridge[idx]) continue;
			if(belong[v]) continue;
			
			belong[v] = cnt;
			q.push(v);
		}
	}
	
}

int main(){
	cin.tie(0), cout.tie(0);
