		if(!belong[i]) get_ebcc(i);
	}
	
	for(int u = 1; u <= n; u++){
		for(auto [v, idx] : g[u]){
			if(isbridge[idx]) tree[belong[u]].push_back(belong[v]);
		}
	}
	
	
	auto bfs = [&](int s) -> pair<int, int>{
		vector<int> dist(cnt + 1, -1);
		queue<int> q;
		q.push(s);
		dist[s] = 0;
		
		int far = s;
		
		while(!q.empty()){
			int u = q.front();
			q.pop();
			if(dist[u] > dist[far]) far = u;
			
			for(int v : tree[u]){
