分三组以上的情况不会比分一组或者两组更优，因为按位与为1需要保证这一位在所有组都为1；

- 只分一组：答案是所有数的异或和
- 分两组：答案是异或线性基的最大值
  - 分两组时，第一组异或和是 y，第二组就是 x ^ y，价值是 

$$
\begin{aligned}
y \,\&\, (x \oplus y) &= y \,\&\, \lnot x \\
&= \Big(\bigoplus_{i\in T} a_i\Big) \,\&\, \lnot x \\
&= \bigoplus_{i\in T}\,(a_i \,\&\, \lnot x)
\end{aligned}
$$

问题转化为求 $ \bigoplus_{i\in T}\,(a_i \,\&\, \lnot x) $ 的最大值，用线性基直接解决即可。


```cpp
#include <bits/stdc++.h>
using namespace std;
#define double long double //提升精度
typedef long long ll;
const int N = 5e5 + 10;
ll mod = 998244353;
ll inf = 1e18 + 10;


ll n, m;
ll ans = 0;

struct xs{
	ll val[62];
	int cnt = 0;
	
	void clear(){
		for(int i = 0; i < 61; i++) val[i] = 0;
		cnt = 0;
	}
	
	void insert(ll x){
		for(int i = 60; ~i; i--){
			if((x >> i) & 1){
				if(val[i]) x ^= val[i];
				else {val[i] = x; return;}
			}
		}
	}
	
	ll query(){
		ll ans = 0;
		for(int i = 60; ~i; i--){
			if((ans ^ val[i]) > ans) ans ^= val[i];
		}
		return ans;
	}
} lb;

int main(){
	ios::sync_with_stdio(false);
	cin.tie(0); cout.tie(0);
	
	int T; cin >> T;
	while(T--){
		int n; cin >> n;
		ll x = 0;
		lb.clear();
		vector<ll> a(n + 1);
		
		for(int i = 1; i <= n; i++) cin >> a[i], x ^= a[i];
		
		for(int i = 1; i <= n; i++) lb.insert(a[i] & (~x));
			
		cout << max(x, lb.query()) << "\n";
	}
	return 0;
}
