##### DFS + 记忆化搜索

注意到构成环只和选中的点有关，和遍历这些点的顺序无关。

所以一个mask可以代表选中若干的点和路径构成的子图。以方便起见，取mask的最为1的位为起点，再记录一个终点，那么`memo[mask][u]`记录的就是从mask的起点到u的路径数量。此时，假如u和起点连通，就可以表明加入u之后新增了`memo[mask][u]`个环。


可以把已经走过的mask的状态`memo[mask][u]`记录下来，这样下次不用重复计算：

```cpp
ll dfs(int mask, int u) {
    if (memo[mask][u] != -1)
        return memo[mask][u];

    int s = __builtin_ctz(mask);
    ll res = 0;

    if (__builtin_popcount(mask) >= 3 && g[u][s])
        res++;

    for (int v = s + 1; v < n; v++) {
        if (!(mask & (1 << v)) && g[u][v]) {
            res += dfs(mask | (1 << v), v);
        }
    }

    return memo[mask][u] = res;
}
```

##### 状压dp 

$$ 
dp[mask][u]=\text{以mask最低为1的位为起点，经过mask中的点，有多少条合法路径能到达当前状态}
$$



```cpp
#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
const int N = 2e5 + 10;


ll dp[1 << 19][20], g[20][20];
ll ans = 0;

int main(){
	ios::sync_with_stdio(false);
	cin.tie(0); cout.tie(0);
	
	int n, m;
	cin >> n >> m;
	for(int i = 0; i < m; i++){
		int x, y;
		cin >> x >> y;
		x--, y--;
		g[x][y] = g[y][x] = 1;
	}
	
	int full = (1 << n) - 1;
	
	for (int i = 0; i < n; i++) {
		dp[1 << i][i] = 1;
	}
	
	for(int mask = 1; mask <= full; mask++){
		int start = __builtin_ctz(mask);
		for(int u = 0; u < n; u++){
			if(!(1 & (mask >> u))) continue; //没有经过u
			if (!dp[mask][u]) continue; //可存在回到u的路径
			
			// 终点可以回到起点，形成环
			if(__builtin_popcount(mask) >= 3 && g[u][start]) ans += dp[mask][u];
			
			//更新按照mask路径走到v之后的路径数量
			for(int v = start + 1; v < n; v++){
				if( ( !(mask & (1 << v)) ) && g[u][v]) dp[mask | (1 << v)][v] += dp[mask][u];
				
			}
		}

	}
	cout << ans / 2;
	return 0;
	
}
