	int n = s.size();
	vector<int> pi(n, 0);
	
	
	for(int i = 1; i < n; i++){
		int j = pi[i - 1];
		
		while(j > 0 && s[i] != s[j]){
			j = pi[j - 1];
		}
		
		if(s[i] == s[j]) j++;
		pi[i] = j;
	}
	
	
	int maxx = 0;
	
	for(int i = 0; i < n - 1; i++) maxx = max(maxx, pi[i]);
	
	int len = pi[n - 1];
	//长度为 len 的前缀也出现过
	while(len > 0 && len > maxx) len = pi[len - 1];
	
	if (len == 0)
		cout << "Just a legend\n";
	else
		cout << s.substr(0, len) << '\n';
}


