##### 哈希做法：二分找到和前缀匹配的最大中间子串，然后找和前缀匹配的最大后缀子串；



```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef long double ld;
typedef unsigned long long ull;
const ll N = 2e5 + 10, M = 2e3+10;
const ll mod = 998244353;
const ll mod1 = 1000000007;
const ll mod2 = 1000000009;
const ll B = 131;


void solve() {
//	auto get = [&](int l, int r) -> pair<ll, ll> {
//		return {}
//	}
	string s;
	cin >> s;
	
	int n = s.size();
	vector<ll> h1(n + 1), h2(n + 1);
	vector<ll> p1(n + 1, 1), p2(n + 1, 1);
	
	for(int i = 0; i < n; i++){
		h1[i + 1] = (h1[i] * B + s[i]) % mod1;
		h2[i + 1] = (h2[i] * B + s[i]) % mod2;
		p1[i + 1] = p1[i] * B % mod1;
		p2[i + 1] = p2[i] * B % mod2;
	}
	
	// 注意只加一次mod不能保证结果非负
	auto get = [&](int l, int r) -> pair<int, int> {
		ll x = (h1[r] - h1[l] * p1[r-l] % mod1 + mod1) % mod1;
		ll y = (h2[r] - h2[l] * p2[r-l] % mod2 + mod2) % mod2;
		return {x, y};
	};
	
	
	// maxx：在中间出现过的最长前缀长度
	int maxx = 0;
	
	//查找每个起点匹配的最长前缀, 不包括整个字符串的前与和后缀
	for(int i = 1; i < n - 1; i++){
		int l = 0, r = n - i - 1;
		
		while(l < r){
			int mid = (l + r + 1) >> 1;
			
			if(get(0, mid) == get(i, i + mid)) l = mid;
			else r = mid - 1;
		}
		maxx = max(maxx, l);
	}
	
	// 从最长候选开始，检查是否也是后缀
	for(int len = maxx; len >= 1; len--){
		if(get(0, len) == get(n - len, n)) {
			cout << s.substr(0, len);
			return;
		}
	}
	cout << "Just a legend";
}


int main() {
	ios::sync_with_stdio(0);
	cin.tie(0), cout.tie(0);
	ll T = 1;
//	cin >> T;
	while (T--) solve();
	return 0;
}
```


##### Z函数做法：$ O(n) $ 维护后缀 


维护 `[l, r]`
```
s = a a b a a b a
    0 1 2 3 4 5 6
          [     ]
          l     r
```

计算 `z[4]`时，在已知区间内，`s[4...]` 的匹配情况与 `s[1...]` 完全相同,

所以可以直接利用 `z[i - l]`

但最多只能相信到右边界 r，因此：

$$ z[i] = min(z[i-l], r-i+1) $$


```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef long double ld;
typedef unsigned long long ull;
const ll N = 2e5 + 10, M = 2e3+10;
const ll mod = 998244353;
const ll mod1 = 1000000007;
const ll mod2 = 1000000009;
const ll B = 131;



void solve() {
	string s; cin >> s;
	
	int n = s.size();
	
	vector<int> z(n);
	int l = 0, r = 0;
	
	for(int i = 1; i < n; i++){
		//利用前面的结果
		if(i <= r) z[i] = min(r - i + 1, z[i - l]);
		
		//继续扩展
		while(i + z[i] < n && s[z[i]] == s[i + z[i]]) z[i]++;
		
		if(i + z[i] - 1 > r) l = i, r = i + z[i] - 1;
		
	}
	
	z[0] = n;
	
	

	int maxx = 0;
	//保证这次匹配在最后一个字符之前结束，不能把后缀那次出现算进去!!!
	for (int i = 1; i < n - 1; i++) maxx = max(maxx, min(z[i], n - i - 1));
	
	for (int len = min(maxx, n - 2); len >= 1; len--) {
		if (z[n - len] >= len) {
			cout << s.substr(0, len);
			return;
		}
	}
	
	cout << "Just a legend";
}



int main() {
	ios::sync_with_stdio(0);
	cin.tie(0), cout.tie(0);
	ll T = 1;
//	cin >> T;
	while (T--) solve();
	return 0;
}

