给定一棵 $n$ 个点的带权树，结点下标从 $1$ 开始到 $n$。求树中所有异或路径的最大值。

如果枚举每个起点和终点 $ (u, v) $， 即使可以使用 $ O(1) $ 的时间计算出异或路径，时间复杂度也是 $ O(n^2) $ 的。

而在树上，点对 $(u, v)$ 间的异或路径可以改写为 $ sum(u) \oplus sum(v) $，其中 $ sum(u) $ 为根节点到 $ u $ 的异或路径。

那么，问题转化为，对于数组 $ sum $，找出两个点使得 $ sum(u) \oplus sum(v) $ 最大。

而字典树可以做到，枚举起点 $ u $ 时，只需要遍历其每个二进制位一遍，就能找到使得 $ sum(u) \oplus sum(v) $最大的点 $ v $.

方法如下：树上的每一层都是一位，从高位到低位，尽可能每一层选择找与  $ sum(u) $ 在该位置相反的节点向下，形成一条路径。

由于高位的权重一定大于低位，所以在每一位贪心地选取该位置的最优解就是整体最优的。这样做的时间复杂度是 $ O(n * 31) $.



```cpp
#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
const int N = 2e5 + 10;

int n, ans, tot;
int h[N], e[N], ne[N], we[N], idx;
int sum[N];
int trie[16*N][2];
//假如n条路径都不共享，最坏情况有31 * n个节点

void add(int a, int b, int w){
	e[idx] = b, ne[idx] = h[a], we[idx] = w, h[a] = idx++;
}

void dfs(int u, int fa){
	for(int i = h[u]; ~i; i = ne[i]){
		int v = e[i], w = we[i];
		if(v != fa) sum[v] = sum[u] ^ w, dfs(v, u);
	}
}

void build(int val, int x){
	for(int i = 30; i >= 0; i--){
		int p = (val >> i) & 1;
		if(!trie[x][p]) trie[x][p] = ++tot;
		x = trie[x][p];
	}
}

int query(int val, int x){
	int ans = 0;
	for(int i = (1 << 30); i; i >>= 1){
		bool p = val & i;
		if(trie[x][!p]) ans += i, x = trie[x][!p]; 
		//该位相反的位置有相应的数，可以取这个数使得异或后的这一位为1
		else x = trie[x][p];
	}
	return ans;
}


int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);
	cin >> n;
	memset(h, -1, sizeof h);
	
	for(int i = 1; i < n; i++){
		int u, v, w;
		cin >> u >> v >> w;
		add(u, v, w);
		add(v, u, w);
	}
	
	//预处理每个节点到根节点路径的异或和
	dfs(1, 0);
	
	for(int i = 1; i <= n; i++) build(sum[i], 0);
	
	for(int i = 1; i <= n; i++) ans = max(ans, query(sum[i], 0));
	
	
	cout << ans << endl;
}
```

