##### Hash做法（结构体，带追加子串）

```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef long double ld;
typedef unsigned long long ull;
const ll N = 2e5 + 10, M = 2e3+10;
const ll mod = 998244353;
const ll mod1 = 1000000007;
const ll mod2 = 1000000009;
const ll B = 131;

struct hashs {
	// 注意初始化元素
	vector<ll> h1{0}, h2{0}, p1{1}, p2{1};
	
	void add(char c) {
		h1.push_back((h1.back() * B + c) % mod1);
		h2.push_back((h2.back() * B + c) % mod2);
		p1.push_back(p1.back() * B % mod1);
		p2.push_back(p2.back() * B % mod2);
	}
	
	void append(const string& s) {
		for (char c : s) add(c);
	}
	
	pair<ll,ll> get(int l, int r) {
		ll x = (h1[r] - h1[l]*p1[r-l]%mod1 + mod)%mod1;
		ll y = (h2[r] - h2[l]*p2[r-l]%mod2 + mod2)%mod2;
		return {x,y};
	}
	
	int size() { return (int)h1.size()-1; }
};


void solve() {
	int n;
	cin >> n;
	
	string ans, s;
	cin >> ans;
	
	hashs ha;
	
	ha.append(ans);
	
	while(cin >> s){
		hashs hs;
		hs.append(s);
		
		int len = 0;
		for(int k = min(ha.size(), hs.size()); k >= 1; k--){
			if(ha.get(ha.size() - k, ha.size()) == hs.get(0, k)){
				len = k;
				break;
			}
		}
		
		for(int j = len; j < s.size(); j++){
			ans += s[j];
			ha.add(s[j]);
		}
	}
	cout << ans;
}



int main() {
	ios::sync_with_stdio(0);
	cin.tie(0), cout.tie(0);
	ll T = 1;
//	cin >> T;
	while (T--) solve();
	return 0;
}
```

> 对给定数组找出一组划分，使得 $B_1 \& B_2 \& \ldots \& B_m$最大，其中$B_i = a_{k_{i,1}} \oplus a_{k_{i,2}} \oplus \cdots \oplus a_{k_{i,p}}$

分三组以上的情况不会比分一组或者两组更优，因为按位与为1需要保证这一位在所有组都为1；

- 只分一组：答案是所有数的异或和
- 分两组：答案是异或线性基的最大值
- 分两组时，第一组异或和是 y，第二组就是 x ^ y，价值是 

$$
\begin{aligned}
y \,\&\, (x \oplus y) &= y \,\&\, \lnot x \\
&= \Big(\bigoplus_{i\in T} a_i\Big) \,\&\, \lnot x \\
&= \bigoplus_{i\in T}\,(a_i \,\&\, \lnot x)
\end{aligned}
$$

问题转化为求 $ \bigoplus_{i\in T}\,(a_i \,\&\, \lnot x) $ 的最大值，用线性基直接解决即可。


```cpp
#include <bits/stdc++.h>
using namespace std;
#define double long double //提升精度
typedef long long ll;
const int N = 5e5 + 10;
ll mod = 998244353;
