ll ans = 0;

struct xs{
	ll val[62];
	int cnt = 0;
	
	void clear(){
		for(int i = 0; i < 61; i++) val[i] = 0;
		cnt = 0;
	}
	
	void insert(ll x){
		for(int i = 60; ~i; i--){
			if((x >> i) & 1){
				if(val[i]) x ^= val[i];
				else {val[i] = x; return;}
			}
		}
	}
	
	ll query(){
		ll ans = 0;
		for(int i = 60; ~i; i--){
			if((ans ^ val[i]) > ans) ans ^= val[i];
		}
		return ans;
	}
} lb;

int main(){
	ios::sync_with_stdio(false);
	cin.tie(0); cout.tie(0);
	
	int T; cin >> T;
	while(T--){
		int n; cin >> n;
		ll x = 0;
		lb.clear();
		vector<ll> a(n + 1);
		
		for(int i = 1; i <= n; i++) cin >> a[i], x ^= a[i];
		
		for(int i = 1; i <= n; i++) lb.insert(a[i] & (~x));
			
		cout << max(x, lb.query()) << "\n";
	}
	return 0;
}
