回文串可以通过相同的前缀和后缀，以及中间的回文串拼成。


> 给定一个由小写英文字母组成的字符串 $s$ 。找出满足以下条件的最长字符串 $t$ ：

> -   $t$ 的长度不超过 $s$ 的长度。
> -   $t$ 是一个回文串。
> -   存在两个字符串 $a$ 和 $b$ （可能为空），使得 $t = a + b$ ，且 $a$ 是 $s$ 的前缀，同时 $b$ 是 $s$ 的后缀。




```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef long double ld;
typedef unsigned long long ull;
const ll N = 2e5 + 10, M = 2e3+10;
const ll mod = 998244353;
const ll mod1 = 1000000007;
const ll mod2 = 1000000009;
const ll B = 131;



void solve() {
	string s;
	cin >> s;
	
	
	int m = s.size();
	int ans = 0;
	while(ans < (m + 1) / 2) {
		if(s[ans] == s[m - ans - 1]) ans++; 
		else break; 
	}
	
	
	if(ans >= m / 2){
		cout << s << '\n';
		return;
	}
	string sub = s.substr(ans, m - 2 * ans);
	
	int n = sub.size();
	
	vector<int> d1(n), d2(n);
	// 奇回文
	for(int i = 0, l = 0, r = -1; i < n; i++){
		int k = (i > r) ? 1 : min(d1[l + r - i], r - i + 1);
		while(i - k >= 0 && i + k < n && sub[i - k] == sub[i + k]) k++;
		
		d1[i] = k--;
		if(i + k > r) l = i - k, r = i + k;
	}
	
	// 偶回文
	for(int i = 0, l = 0, r = -1; i < n; i++){
		int k = (i > r) ? 0 : min(d2[l + r - i + 1], r - i + 1);
		while(i - k - 1 >= 0 && i + k < n && sub[i - k - 1] == sub[i+k]) k++;
		
		d2[i] = k--;
		if(i + k > r) l = i - k - 1, r = i + k;
	}
	
	int best = 0, start = 0;
	
	for(int i = 0; i < n; i++){
		int L = i - d1[i] + 1;
		int R = i + d1[i] - 1;
		int len = 2 * d1[i] - 1;
		
		if((L == 0 || R == n - 1) && len > best){
			best = len;
			start = L;
		}
		
		L = i - d2[i];
		R = i + d2[i] - 1;
		len = 2 * d2[i];
		
		if((L == 0 || R == n - 1) && len > best){
			best = len;
			start = L;
		}
	}
	
	
	cout << s.substr(0, ans) << sub.substr(start, best) << s.substr(m-ans, ans) << '\n';
}



int main() {
	ios::sync_with_stdio(0);
	cin.tie(0), cout.tie(0);
	ll T = 1;
	cin >> T;
	while (T--) solve();
	return 0;
}
```

> 给定一个长度为 \(n\) 的非负整数数组 \(a\)，选择一个长度至少为 2 的连续区间 \([l,r]\)。
> 设该区间的最大值为：
> \[ m=\max(a_l,a_{l+1},\ldots,a_r) \]
> 定义区间的价值为：
> \[ f(l,r)=(a_l\&m)\oplus\cdots\oplus(a_r\&m)\]
> 求所有合法区间的最大价值。
> 数据范围为 \(n\le 2\times10^5\)，\(0\le a_i<2^{18}\)，显然不能枚举全部 \(O(n^2)\) 个区间。




OR 和 XOR 对 AND 有分配律：

$$ a|(b\&c)=(a|b)\&(a|c) $$

$$ a\&(b\oplus c)=(a\&b)\oplus(a\&c). $$

> 但 OR 和 XOR 不能对 AND 分配


因此，

$$ (a_l \mathbin{\&} m) \oplus (a_{l+1} \mathbin{\&} m) \oplus \cdots \oplus (a_r \mathbin{\&} m) \\
= (a_l \oplus a_{l+1} \oplus \cdots \oplus a_r) \mathbin{\&} m \\
= (p_{l-1} \oplus p_r) \mathbin{\&} m. $$

似乎前面括号转化为了之前找两个异或值最大的形式。但是相比之下多了一步运算，就是要与二者中间的最大值 $ m $ 进行与运算之后的结果最大。

为了方便地找出区间中的最大值，可以使用笛卡尔树来做到这一点。

如果 $v = \mathbf{LCA}(l, r)$，那么这个区间的值就是

$$(p_{l-1} \oplus p_r) \mathbin{\&} a_v.$$

之后，我们从 $ [0, 2^{18}) $ 的值域里从高位向低位枚举所有可能的答案 $ m $，检查两点：

- 1.$ m $ 是否是当前节点作为最大值时的合法答案，也就是 $ m \& a[v] = m $ 是否成立（由笛卡尔树的性质，$ a[v] $ 是其左子树到右子树的最大值），成立之后才有可能是当前节点作为最大值时的答案；
- 2.$ a[v] $作为最大值的区间中，是否存在两个点（已经处理成异或前缀和），满足 $ s[i] \oplus s[j] = m $ ；
  - 利用类似上面异或路径和的思想，可以枚举 $ i $， 查找区间内是否存在合法的 $ s[j] = m \oplus s[i] $（尽管我们并不关心这样的$ s[j] $是什么、具体在哪个位置。
  - 可以对每个节点两边的子树递归地向下遍历，这样上一层可以复用下一层的答案。同时，枚举的时候可以选择枚举小的子树，因为查找另一边子树是否存在符合条件的答案总是 $ O(1) $的。



区间的枚举与还原细节很多很难写（已力竭）

```cpp
#include <bits/stdc++.h>
using namespace std;
#define double long double 
typedef long long ll;
const int N = 2e5 + 10;
ll mod = 998244353;
ll inf = 1e18 + 10;

int n, m, a[N], p[N], s[N], lc[N], rc[N], root, cnt[1 << 18];
bool flag;

void build(int v, int l, int r){
	if(l > r) return;
	
	bool okv = ((a[v] & m) == m);
	if(v - l <= r - v){//启发式合并：枚举小的一边
		if(lc[v]) build(lc[v], l, v - 1); //先处理左孩子（小的）
		for(int i = l; i < v; i++) cnt[s[i]]--; //清空左边区间更新的cnt
		if(rc[v]) build(rc[v], v + 1, r);
		if(okv && cnt[s[v - 1] ^ m] > 0) flag = true;
		//在纳入v之前检查 v-1 ，避开非法的 (v-1, v)
		cnt[s[v]]++;
		if(okv){
			for(int i = v - 2;  i >= l - 1; i--){//不检查 v-1的情况
				if(cnt[s[i] ^ m] > 0) {flag = true; break;}
				//区间 [l', r'] 的异或 = p_{l'-1} ⊕ p_{r'}
			}
		}

		for(int i = l; i < v; i++) cnt[s[i]]++;//把左边区间更新的cnt加回来
	}
	else{
		if(rc[v]) build(rc[v], v + 1, r);
		for(int i = v + 1; i <= r; i++) cnt[s[i]]--;
		if(lc[v]) build(lc[v], l, v - 1);
		cnt[s[v - 1]]--; //检查v时先暂时删去v - 1                              
		cnt[s[l - 1]]++; 
		if(okv && cnt[s[v] ^ m]) flag = 1;
		cnt[s[v - 1]]++;  

		if(okv){
			for(int i = v + 1; i <= r; i++){
				if(cnt[s[i] ^ m]) {flag = 1; break;}
			}
		}
		cnt[s[l - 1]]--;                          
		for(int i = v; i <= r; i++) cnt[s[i]]++; //包括当前节点也要补回去
	}
}

bool check(){
	for(int i = 0; i <= n; i++) s[i] = p[i] & m;
	flag = 0;
	build(root, 1, n);
	for(int i = 1; i <= n; i++) cnt[s[i]] = 0; // 只清用过的位置
