首先由数据范围可以想到，对于每次查询，可以由大到小枚举所有可能的答案，然后检查该答案下 $ u $ 和 $ v $ 的联通性。可以使用并查集来维护联通性。

但是枚举异或和仍然需要 $ 2^{12} $ 次，又由于按位与的性质，若答案的某一位置为 $ 1 $， 则路径上所有边的权值在该位都为 $ 1 $，因此可以从高位进行逐位贪心，检查当前位为 $ 1 $ 时是否联通，如果是则保留该位置为 $ 1 $，可以得到联通情况下的最大答案。

- 加边：每次加边，在并查集更新两个端点的的所有可能的联通性；
  - 剪枝：注意只需要更新 $ w $ 的子集，只有子集才会联通。所以递归更新子掩码的联通性即可。同时一个掩码联通代表其子掩码必定联通，可以在这里停止递归。
- 查询：由大到小对每一位查询，该位置为 $ 1 $ 时是否在同一联通块内。



```cpp
struct dsu{
	vector<int> fa; 
	int cnt;
	dsu(int n): fa(n, -1), cnt(n){};
	//fa为正时记录节点的根节点，为负时作为根节点记录该联通块的大小
	//cnt记录联通块的数量
	
	int find(int x){//返回根节点编号
		return fa[x] < 0 ? x : fa[x] = find(fa[x]);
	}
	
	
	int merge(int x, int y){
		x = find(x), y = find(y);
		if(x == y) return false;
		fa[x] += fa[y], fa[y] = x, cnt--;
		return cnt;
	}
};

void solve(){
	int n, q;
	cin >> n >> q;
	
	vector path(1 << 12, dsu(n + 1));
	
	ll ans = 0;
	while(q--){
		char op; cin >> op;
		int x, y; cin >> x >> y;
		if(op == '+'){
			int w; cin >> w;
			auto add = [&](auto&& add, int w) -> void {
				if(path[w].merge(x, y)){
					for(int i = 0; i < 12; i++){
						if(w >> i & 1){//递归更新w的所有子集
							add(add, w ^ (1 << i));
						}
					}
				}
			};
			add(add, w);
		}
		else{
			int res = 0;
			for(int i = 11; i >= 0; i--){
				if (path[res | (1 << i)].find(x) == path[res | (1 << i)].find(y)){
					res |= (1 << i);
				}
			}
			if(!(path[0].find(x) == path[0].find(y))) res = -1; //没有联通
			ans += res;
		}
	}
	cout << ans << "\n";
}

```

