影响当前满意度的三个维度：时间点、花费金额、付款状态。

付款状态只有四种：

- 0：都没有付过钱（或都付过钱）
- 1：A刚付过钱
- 2：B刚付过钱
- 3：A、B都付过钱，但G还没有付过钱

而期望dp一般按照时间点从后往前进行。一般只依赖于前一个时间点转移的，用一个数组保存上一个时间点的信息即可。

因此，对 $ k = n, n - 1, …, 1 $ 天，使用二维数组 `dp2` 记录 第 $ k $ 到第 $ n $ 天，每个花销和每个状态下的满意度最大值。由于每个状态会以确定的概率转移到第 $ k + 1 $ 天的某个状态，所以用上一轮的 `dp` 结果进行概率转移即可。

时间复杂度 $ O(nm) $。

```cpp
#define double long double //提升精度
typedef long long ll;
const int N = 1e6 + 10;
ll mod = 998244353;
ll inf = 1e18 + 10;
ll inf = 1e18 + 10;


ll n, m;
ll ans = 0;


int main(){
	ios::sync_with_stdio(false);
	cin.tie(0); cout.tie(0);
	
	int n, m; cin >> n >> m;
	
	vector<array<int, 6>> v(n);
	for (auto& [a, b, c, d, e, x] : v) {
		cin >> a >> b >> c >> d >> e >> x;
	}
	
	// 倒序处理
	reverse(v.begin(), v.end());
	
	vector<array<double, 4> > dp(m + 1);
	
	for(auto & [a, b, c, d, e, x] : v){
		vector<array<double, 4>> dp2(m + 1);
		for (int i = 0; i <= m; i++) {
			dp2[i].fill(-inf);
		}
		
		
		double p = 0.01l * x;
		double q = 1 - p;
	
		//先处理在食堂吃的情况
		for(int i = 0; i <= m - b; i++){
			dp2[i + b][0] = max(dp2[i + b][0], a + p * dp[i][1] + q * dp[i][2]);
			dp2[i + b][1] = max(dp2[i + b][1], a + p * dp[i][1] + q * dp[i][3]);
			dp2[i + b][2] = max(dp2[i + b][2], a + p * dp[i][3] + q * dp[i][2]);
			dp2[i + b][3] = max(dp2[i + b][3], a + p * dp[i][3] + q * dp[i][3]);
		}
		
		
		//出出租车费
		for(int i = 0; i <= m - d - e; i++){
			dp2[i + d + e][3] = max(dp2[i + d + e][3], c + dp[i][0]);
		}
		
		
		//不出出租车费
		for(int i = 0; i <= m - d; i++){
			dp2[i + d][0] = max(dp2[i + d][0], c + p * dp[i][1] + q * dp[i][2]);
			dp2[i + d][1] = max(dp2[i + d][1], c + p * dp[i][1] + q * dp[i][3]);
			dp2[i + d][2] = max(dp2[i + d][2], c + p * dp[i][3] + q * dp[i][2]);
		}
		
		dp = dp2;
	}
	
	double ans = -inf;
	
	for(int i = 0; i <= m; i++) ans = max(ans, dp[i][0]);
	
	if(ans < 0) cout << "-1\n";
	else cout << fixed << setprecision(12) << ans << "\n";
	
