	for(int i = 1; i <= n; i++){
		cin >> a[i];
		int r = a[i];
		a[i] = __gcd(a[i], x);
		for(auto j : v[a[i]]) sum[j] += r;
	}
	
	ll ans = 0;
	for(auto j : v[x]) ans = max(ans, sum[j]);
	cout << ans << "\n";
