	for(int i = 2; i <= N - 1; i++){
		if(!p[i]){
			for(int j = i; j <= N - 1; j += i) p[j] = 1, v[j].push_back(i);
		}
	}
	int T; cin >> T;
	while(T--) solve();
	return 0;
}
