	for(int i = 1; i < n; i++){
		if(s[i] != s[i - 1]) pre[i] = 1, ans += i * (n - i);//注意这里容易爆int
		else pre[i] = 0;
	}
	
	
	for(int i = 0; i < n; i++){
		if(s[i] == '0') cnt0++;
		else cnt1++;
	}
	
	cout << (ans + cnt0 * cnt1) / 2 << ' ';
	
	while(q--){
		int p; cin >> p;
		if(p != 1){
			if(pre[p - 1] == 0) pre[p - 1] = 1, ans += (p - 1) * (n - p + 1);
			else pre[p - 1] = 0, ans -= (p - 1) * (n - p + 1);
		} 
		if(p != n){
			if(pre[p] == 0) pre[p] = 1, ans += p * (n - p);
			else pre[p] = 0, ans -= p * (n - p);
		}
		
		if(s[p - 1] == '0') cnt0--, cnt1++, s[p - 1] = '1';
		else cnt1--, cnt0++, s[p - 1]= '0';
		
		cout << (ans + cnt0 * cnt1) / 2 << ' ';
	}
	
	cout << "\n";
}
```

如果有两个相邻的相同字符，就可以选择在两次分别删除其中一个，两次删除之后得到的字符串是相同的；

否则，删除尾部的字符串，可以保证被删除位置之前的前缀是相同的。


