	for(int i = 1; i <= n; i++) cin >> a[i], p[i] = (p[i - 1] + a[i]) % k;
	
	for(int i = k + 1; i <= n; i++){
		cnt[p[i - k - 1]]++;//左侧已经可以合法的位置
		ans += cnt[p[i]];//提取对当前右端点已经合法的左端点
	}
	
	cout << ans << endl;
	
	
}
