> 可以一个矩形 n×m 矩阵 a 进行任意多次以下操作：
> 在一次移动中，可以选择任意一列列并循环移动此列中的元素。
> 完成循环移位后，假设第 i 行最大值等于 ri 。 r1+r2+…+rn 的最大可能值是多少？$ (1≤n≤12, 1≤m≤2000) $

- 由于 $ m $ 的数量过大，可以对列进行排序，取前 $ min(n, m) $ 个列进行考虑。
- 状态转移：`val[mask]` 存储当前列贡献 `mask` 位置时的最大值
- 于是，从小到大枚举 `mask` 代表这些位置的最大值行已经确定，再枚举 `mask` 补集的子集，向当中添加当前列可能做出的贡献。


```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef long double ld;
typedef unsigned long long ull;
const ll N = 12, M = 2e3+10;
const ll mod = 676767677;

int g[N][M];

void solve(){
	int n, m;
	cin >> n >> m;

	for(int i = 0; i < n; i++){
		for(int j = 0; j < m; j++){
			cin >> g[i][j];
		}
	}


	vector<pair<int, int> > cols(m);
	for(int j = 0; j < m; j++){
		int maxx = 0;
		for(int i = 0; i < n; i++){
			maxx = max(maxx, g[i][j]);
		}
		cols[j] = {maxx, j};
	}

	sort(cols.rbegin(), cols.rend());

	int k = min(n, m);

	vector<ll>  dp(1 << n, -1);
	dp[0] = 0;

	for(int t = 0; t < k; t++){
		int col = cols[t].second;

		vector<ll> val(1 << n, 0);

		for(int shift = 0; shift < n; shift++){
			vector<ll> sum(1 << n, 0);

			for(int mask = 1; mask < (1 << n); mask++){
				int bit = __builtin_ctz((unsigned)mask);
				int pre = mask ^ (1 << bit);

				int row = (bit + shift) % n;

				sum[mask] = sum[pre] + g[row][col];

				val[mask] = max(sum[mask], val[mask]);

			}
		}

		vector<ll> ndp = dp;

		for(int mask = 0; mask < (1 << n); mask++){
			if(dp[mask] == -1) continue;
			int rest = ((1 << n) - 1) ^ mask;
			for(int subset = rest; subset; subset = (subset - 1) & rest){
				ndp[mask | subset] = max(ndp[mask | subset] , dp[mask] + val[subset]);
			}
		}
		dp = ndp;
	}
	cout << dp[(1 << n) - 1] << "\n";
}

int main(){
	ios::sync_with_stdio(0);
	cin.tie(0), cout.tie(0);
	ll T = 1; 
	cin >> T;
	while(T--) solve();
	return 0;
}
