	int n, k;
	cin >> n >> k;

	int a = 0, b = 0;
	for (int i = 0, x; i < n; i++) {
		cin >> x;
		a += (x % 2 != k % 2);
	}
	for (int i = 0, x; i < n; i++) {
		cin >> x;
		b += (x % 2 != k % 2);
	}

	cout << (a >= b ? "YES\n" : "NO\n");
}


int main(){
	ios::sync_with_stdio(0);
	cin.tie(0), cout.tie(0);
	ll T = 1; 
	cin >> T;
	while(T--) solve();
	return 0;
}


