typedef long long ll;
typedef long double ld;
typedef unsigned long long ull;
const ll N = 2e5 + 10, M = 2e3+10;
const ll mod = 998244353;

ll dp[N][3];

void solve() {
	int n, l;
	cin >> n >> l;


	vector<ll> a(n + 10, 0), sum(n + 10, 0);


	for(int i = 1; i <= n; i++) cin >> a[i];

	sort(a.begin() + 1, a.begin() + n + 1);

	for(int i = 1; i <= n; i++) sum[i] = sum[i - 1] + a[i];

	//除了最大值全为0
	ll  ans = sum[n - 1];

	for(int i = 1; i * i < l; i++){
		int pos = upper_bound(a.begin() + 1, a.begin() + n, i)  - a.begin();
		ans = min(ans, sum[n - 1] - sum[pos - 1] - 1ll * (n - pos) * i + max(0ll, a[n] - (l - 1) / i));
	}

	cout << ans << "\n";

}


int main(){
	ios::sync_with_stdio(0);
	cin.tie(0), cout.tie(0);
	ll T = 1; 
	cin >> T;
	while(T--) solve();
	return 0;
