### 哈希做法：二分找到和前缀匹配的最大中间子串，然后找和前缀匹配的最大后缀子串；



```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef long double ld;
typedef unsigned long long ull;
const ll N = 2e5 + 10, M = 2e3+10;
const ll mod = 998244353;
const ll mod1 = 1000000007;
const ll mod2 = 1000000009;
const ll B = 131;


void solve() {
//	auto get = [&](int l, int r) -> pair<ll, ll> {
//		return {}
//	}
	string s;
	cin >> s;

	int n = s.size();
	vector<ll> h1(n + 1), h2(n + 1);
	vector<ll> p1(n + 1, 1), p2(n + 1, 1);

	for(int i = 0; i < n; i++){
		h1[i + 1] = (h1[i] * B + s[i]) % mod1;
		h2[i + 1] = (h2[i] * B + s[i]) % mod2;
		p1[i + 1] = p1[i] * B % mod1;
		p2[i + 1] = p2[i] * B % mod2;
	}

	// 注意只加一次mod不能保证结果非负
	auto get = [&](int l, int r) -> pair<int, int> {
		ll x = (h1[r] - h1[l] * p1[r-l] % mod1 + mod1) % mod1;
		ll y = (h2[r] - h2[l] * p2[r-l] % mod2 + mod2) % mod2;
		return {x, y};
	};


	// maxx：在中间出现过的最长前缀长度
	int maxx = 0;

	//查找每个起点匹配的最长前缀, 不包括整个字符串的前与和后缀
	for(int i = 1; i < n - 1; i++){
		int l = 0, r = n - i - 1;

		while(l < r){
			int mid = (l + r + 1) >> 1;

			if(get(0, mid) == get(i, i + mid)) l = mid;
			else r = mid - 1;
		}
		maxx = max(maxx, l);
	}

	// 从最长候选开始，检查是否也是后缀
	for(int len = maxx; len >= 1; len--){
		if(get(0, len) == get(n - len, n)) {
			cout << s.substr(0, len);
			return;
		}
	}
	cout << "Just a legend";
}


int main() {
	ios::sync_with_stdio(0);
	cin.tie(0), cout.tie(0);
	ll T = 1;
//	cin >> T;
	while (T--) solve();
	return 0;
}
```


#### Z函数做法：$ O(n) $ 维护后缀 


维护 `[l, r]`
```
s = a a b a a b a
    0 1 2 3 4 5 6
          [     ]
          l     r
```

计算 `z[4]`时，在已知区间内，`s[4...]` 的匹配情况与 `s[1...]` 完全相同,

所以可以直接利用 `z[i - l]`

但最多只能相信到右边界 r，因此：

$$ z[i] = min(z[i-l], r-i+1) $$


```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef long double ld;
typedef unsigned long long ull;
const ll N = 2e5 + 10, M = 2e3+10;
const ll mod = 998244353;
const ll mod1 = 1000000007;
const ll mod2 = 1000000009;
const ll B = 131;



void solve() {
	string s; cin >> s;

	int n = s.size();

	vector<int> z(n);
	int l = 0, r = 0;

	for(int i = 1; i < n; i++){
		//利用前面的结果
		if(i <= r) z[i] = min(r - i + 1, z[i - l]);

		//继续扩展
		while(i + z[i] < n && s[z[i]] == s[i + z[i]]) z[i]++;

		if(i + z[i] - 1 > r) l = i, r = i + z[i] - 1;

	}

	z[0] = n;



	int maxx = 0;
	//保证这次匹配在最后一个字符之前结束，不能把后缀那次出现算进去!!!
	for (int i = 1; i < n - 1; i++) maxx = max(maxx, min(z[i], n - i - 1));

	for (int len = min(maxx, n - 2); len >= 1; len--) {
		if (z[n - len] >= len) {
			cout << s.substr(0, len);
			return;
		}
	}

	cout << "Just a legend";
}



int main() {
	ios::sync_with_stdio(0);
	cin.tie(0), cout.tie(0);
	ll T = 1;
//	cin >> T;
	while (T--) solve();
	return 0;
}

```

##### Manacher 板子

> 给定一个由小写英文字母组成的字符串 $s$ 。找出满足以下条件的最长字符串 $t$ ：

> -   $t$ 的长度不超过 $s$ 的长度。
> -   $t$ 是一个回文串。
> -   存在两个字符串 $a$ 和 $b$ （可能为空），使得 $t = a + b$ ，且 $a$ 是 $s$ 的前缀，同时 $b$ 是 $s$ 的后缀。




```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef long double ld;
typedef unsigned long long ull;
const ll N = 2e5 + 10, M = 2e3+10;
const ll mod = 998244353;
const ll mod1 = 1000000007;
const ll mod2 = 1000000009;
const ll B = 131;



void solve() {
	string s;
	cin >> s;


	int m = s.size();
	int ans = 0;
	while(ans < (m + 1) / 2) {
		if(s[ans] == s[m - ans - 1]) ans++; 
		else break; 
	}


	if(ans >= m / 2){
		cout << s << '\n';
		return;
	}
	string sub = s.substr(ans, m - 2 * ans);

	int n = sub.size();

	vector<int> d1(n), d2(n);
	// 奇回文
	for(int i = 0, l = 0, r = -1; i < n; i++){
		int k = (i > r) ? 1 : min(d1[l + r - i], r - i + 1);
		while(i - k >= 0 && i + k < n && sub[i - k] == sub[i + k]) k++;

		d1[i] = k--;
		if(i + k > r) l = i - k, r = i + k;
	}

	// 偶回文
	for(int i = 0, l = 0, r = -1; i < n; i++){
		int k = (i > r) ? 0 : min(d2[l + r - i + 1], r - i + 1);
		while(i - k - 1 >= 0 && i + k < n && sub[i - k - 1] == sub[i+k]) k++;

		d2[i] = k--;
		if(i + k > r) l = i - k - 1, r = i + k;
	}

	int best = 0, start = 0;

	for(int i = 0; i < n; i++){
		int L = i - d1[i] + 1;
		int R = i + d1[i] - 1;
		int len = 2 * d1[i] - 1;

		if((L == 0 || R == n - 1) && len > best){
			best = len;
			start = L;
		}

		L = i - d2[i];
		R = i + d2[i] - 1;
		len = 2 * d2[i];

		if((L == 0 || R == n - 1) && len > best){
			best = len;
			start = L;
		}
	}


	cout << s.substr(0, ans) << sub.substr(start, best) << s.substr(m-ans, ans) << '\n';
}



int main() {
	ios::sync_with_stdio(0);
	cin.tie(0), cout.tie(0);
	ll T = 1;
	cin >> T;
	while (T--) solve();
	return 0;
}
```

