	nxt[n].fill(n);

	for(int i = n - 1; i >= 0; i--){
		nxt[i] = nxt[i + 1];
		nxt[i][s[i] - '0'] = i;
	}

	auto get = [&](int l, string t){
		int p = l;
		for(char c : t){
			p = nxt[p][c - '0'];
			if(p == n) return n;
			p++;
		}
		return p - 1;
	};

	vector<ll> a(n + 2), b(n + 2);

	auto add = [&](ll l, ll r, ll num1, ll num2){
		if(l > r) return;
		a[l] += num1;
		a[r + 1] -= num1;
		b[l] += num2;
		b[r + 1] -= num2;
	};


	//枚举左端点，查找右端点给区间内造成的贡献
	for(int l = 0; l < n; l++){
		int r25 = get(l, "2025");
		int r26 = get(l, "2026");

		//以该左端点的区间全部是好序列
		if(r25 >= r26) continue;


		add(l, r25, 0, r26 - r25);
		add(r25 + 1, r26 - 1, -1, r26);
	}


	ll suma = 0, sumb = 0;

	for(int i = 0; i < n; i++){
		ll tot = 1ll * (i + 1) * (n - i);
		suma += a[i];
		sumb += b[i];

		ll bad = suma * i + sumb;
		cout << tot - bad << " ";
	}
	cout << "\n";

}

int main(){
	int T = 1;
