##### O（log（n））时间实现质因数分解

###### 注意solve里面反复开大vector容易爆T，memset则快多了

###### 注意质因数乘积可能会很大，可以用set维护为奇数的质因数，每次需要计算乘积的时候才遍历set乘起来


7 是由 \(a_i\le10^6\) 的值域限制算出来的，表示一个不超过 \(10^6\) 的正整数，最多能有多少个不同的质因子。

思路是：要让不同质因子尽可能多，就从最小的质数开始相乘。
\[
\begin{aligned}
2\cdot3\cdot5\cdot7\cdot11\cdot13\cdot17
&=510510\le10^6\\
2\cdot3\cdot5\cdot7\cdot11\cdot13\cdot17\cdot19
&=9699690>10^6
\end{aligned}
\]

所以：
\[
\boxed{\text{任意 }a_i\le10^6\text{，最多有 7 个不同质因子}}
\]

可以用这个性质限制set的大小。

```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef unsigned long long ull;
const ll N = 5e5+10, M = 1e6+10;
const ll mod = 998244353;
vector<int> primes;
int spf[M];
int cnt1[M];
//vector<int> cnt1(M, 0);

void sieve(){
	for(int i = 2; i < M; i++){
		if(!spf[i]) spf[i] = i, primes.push_back(i);

		for(int p : primes){
			if(1ll * i * p >= M) break;
			spf[i * p] = p;
			if(i % p == 0) break;
		}
	}
}


void solve() {
	int n;
	cin >> n;

	// A：局部 vector，/每次都开这么大的vector会爆T
//	vector<int> cnt1(M, 0);

// B：全局 vector，重复 fill
//	fill(cnt1.begin(), cnt1.end(), 0);

// C：全局静态数组，重复 memset，最快
//	memset(cnt1, 0, sizeof cnt1);

	vector<ll> a(n + 1);

	set<ll> se;
	for(int i = 1; i <= n; i++) cin >> a[i];

	for(int i = 1; i <= n; i++){
		ll x = a[i], ker = 1;
		while(x > 1){
			int p = spf[x], cnt = 0;
			while(x % p == 0) cnt ^= 1, x /= p;
			if(cnt) ker *= p;
		}
		cnt1[ker]++;
	}


	ll ans = 0;
	for(int i = 1; i <= n; i++){
		ll x = a[i], ker = 1;
		while(x > 1){
			int p = spf[x], cnt = 0;
			while(x % p == 0) cnt ^= 1, x /= p;
			if(cnt){
				if(se.count(p)) se.erase(p);
				else se.insert(p);
			}
		}

		bool flag = 0;

		//小优化：因为最小的 8 个不同质数的乘积都已经超过 \(10^6\)，这样的前缀不可能有贡献。
//		if (se.size() > 7) continue;
		//最好乘之前检查
		for (auto p : se) {
			if (ker > 1000000ll / p) {flag = 1; break;}
			ker *= p;
		}
		if(flag) continue;
		ans += cnt1[ker];
	}
	cout << ans << "\n";
}


int main() {
	ios::sync_with_stdio(0);
	cin.tie(0), cout.tie(0);
	sieve();
	ll T;
	cin >> T;
	while (T--) solve();
	return 0;
}

```

- 将每个位置有多少种可能放数的方式，转换成记录每个数有多少个可放的位置，最后乘起来就是合法排列，
- 倒序枚举每个数字，如果这个数字出现在限制中过，那么它一定在最低层的子树内，这是它可以选择的位置；如果没有出现过，那么可以出现在当前空余的任意位置，因为倒序枚举，保证了它出现在任一个子树都不会更替子树要求的最大值。
- 如此，每放一个位置，就把这个位置从剩余的选择中扣掉，这样可以保证每次选择的独立性，所以每个数字选择的乘积就是合法的放数的方案数
- 注意检查两个限制，违反会使得答案按变成0：
  - 同一个最大值限制只能出现在同一条祖先链上
  - 子树的最大值限制不能超过祖先


```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef unsigned long long ull;
const ll N = 5e5+10, M = 1e6+10;
const ll mod = 998244353;

void solve() {
	int n, q;
	cin >> n >> q;

	int m = 1 << n;

	int sz = 2 * m;

	vector<int> lim(sz), up(sz), dep(sz), v(m + 1), cnt(sz), deepest(m + 1);

	for(int i = 1; i < sz; i++) dep[i] = dep[i / 2] + 1;

	lim[1] = m;
	deepest[m] = 1;

	bool bad = 0;

	for(int i = 0; i < q; i++){
		int u, x;
		cin >> u >> x;

		if(lim[u] && lim[u] != x) bad = 1;

		lim[u] = x;
		deepest[x] = max(deepest[x], u);
	}


	//检查所有已经有限定值的节点，同一个值是否出现在同一条祖先链上
	for(int u = 1; u < sz; u++){
		if(!lim[u]) continue;

		int x = lim[u];
		int w = deepest[x];

		//判断w（取值为x的最末节点）是否是u的儿子
		if((w >> (dep[w] - dep[u])) != u) bad = 1;
	}

	// 从根向下传递最大允许值，并检查同一条链上的限制值是否单调减小
	up[1] = m;
	for(int u = 2; u < sz; u++){
		up[u] = up[u / 2];

		if(lim[u]){
			if(lim[u] > up[u]) bad = 1;

			up[u] = lim[u];
		}
	}

	if(bad){cout << 0 << "\n"; return;}

	// 统计最大允许值恰好为 x 的叶子数量
	for(int u = m; u < sz; u++){
		v[up[u]]++;
		cnt[u] = 1;
	}

	// cnt[u]: u 子树内，上界等于 up[u] 的叶子数
	for(int u = m - 1; u >= 1; u--){
		if(up[u * 2] == up[u]) cnt[u] += cnt[u * 2];
		if(up[u * 2 + 1] == up[u] ) cnt[u] += cnt[u * 2 + 1];
	}

	ll ans = 1;
	int sum = 0;


	//枚举每个数字可以放的位置
	for(int x = m; x >= 1; x--){
		sum += v[x];  // 当前数字可用的空位总数

		int res;

		if(deepest[x]) res = cnt[deepest[x]];
		else res = sum;

		if(res <= 0) {cout << 0 << "\n"; return;}

		ans = ans * res % mod;
		sum--; // 选了一个位置，占用一个空位
	}
	cout << ans << "\n";
}


int main() {
	ios::sync_with_stdio(0);
	cin.tie(0), cout.tie(0);
	ll T = 1;
//	cin >> T;
	while (T--) solve();
	return 0;
}

```

###### 组合数板子


```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef unsigned long long ull;
const ll N = 5e5+10, M = 1e6+10;
//const ll mod = 998244353;
const ll mod = 1000000007;
ll fac[N], invfac[N];

ll qpow(ll base, ll idx){
	ll res = 1;
	while(idx){
		if(idx & 1) res = res * base % mod;
		base = base * base % mod;
		idx >>= 1;
	}
	return res;
}

void init(){
	fac[0] = 1;

	for(int i = 1; i < N; i++) fac[i] = fac[i - 1] * i % mod;

	invfac[N - 1] = qpow(fac[N - 1], mod - 2);

	for(int i = N - 1; i >= 1; i--) invfac[i - 1] = invfac[i] * i % mod;
}

// 统计长度为 len，前缀最大值位置恰好为 p 的排列数
// 用循环代替递归过程
ll calc(vector<int> &p, int len){
	ll res = 1;

	for(int i = p.size() - 1; i >= 0; i--){
		int pos = p[i];

		res = res * fac[len - 1] % mod * invfac[pos - 1] % mod;

		len = pos - 1;
	}

	return res;
}

void solve() {
	int n, m1, m2;
	cin >> n >> m1 >> m2;

	vector<int> p(m1), s(m2);

	for(int i = 0; i < m1; i++) cin >> p[i];
	for(int i = 0; i < m2; i++) cin >> s[i];

	if(p[0] != 1 || s.back() != n || p.back() != s[0]) {cout << "0\n"; return;}

	int k = p.back();

	ll ans = fac[n - 1] * invfac[k - 1] % mod * invfac[n - k] % mod;


	// 左半边：去掉全局最大值的位置 k
	p.pop_back();


	// 右半边：反转，并转换成从 1 开始的坐标
	vector<int> r;
	for(int i = m2 - 1; i >= 1; i--) r.push_back(n - s[i] + 1);

	ans = ans * calc(p, k - 1) % mod;
	ans = ans * calc(r, n - k) % mod;

	cout << ans << "\n";

}


int main() {
	ios::sync_with_stdio(0);
	cin.tie(0), cout.tie(0);
	init();
	ll T = 1;
	cin >> T;
	while (T--) solve();
	return 0;
}
```

- 任取一条路径相当于选择两个不同的端点，选择有 $ n(n + 1)/2 $ 种，那么任选两条路径的选择有   $ (n(n + 1)/2)^2 $ 种，分母确定。
- 求分子即为所有路径共同边数的平方加和
- 转换枚举对象：求所有路径是困难的，转而考虑所有枚举每条边，考虑每条边会给答案造成多少贡献
- 对于一个 $ X $ 的取值，有$ X^2 = (\sum_i{e_i})^2 = \sum_i{e_i^2} + \sum{e_i e_j}$，因此，只需要记录每条边在第一部分和第二部分产生的贡献即可
- 第一部分只需要考虑一条边出现在不同路径上的次数，一个端点在子树内和一个端点在子树外，为 $ ((n - size(v))  size(v))^2 $
- 第二部分，注意每个 $ {i, j} $ 对会出现两次，因此结果需要乘以2，答案需要考虑路径的一端在子树内，另一端在祖先节点或者兄弟子树内的情况，
  - 对于祖先的情况，答案为
 \[
2\sum_{u\ne1}
\sum_{\substack{v\in subtree(u)\\v\ne u}}
siz[v]^2(n-siz[u])^2
\]
因为对固定的 \(u\)，\((n-siz[u])^2\) 是常数，所以提出来：
\[
\boxed{
2\sum_{u\ne1}
(n-siz[u])^2
\underbrace{\left(sum[u]-siz[u]^2\right)}_{\text{后代边贡献之和}}
}
\]

   - 对于两条边处于不同分支的情况，需要计算 $ \sum{size(u)^2size(v)^2} $
   - **利用恒等式**：
\[
\boxed{
2\sum_{i<j}a_i a_j
=\left(\sum_i a_i\right)^2-\sum_i a_i^2
}
\]


###### 利用前缀展开子树两两乘积枚举 $ O(n^2) $ 压缩到 $ O(n) $


```cpp
ans = (ans + 2 * pre % mod * sum[v]) % mod;
pre = (pre + sum[v]) % mod;
```

