###### 使用循环完成子节点向上统计


```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef unsigned long long ull;
const ll N = 1e5+10, M = 1e6+10;
const ll mod = 998244353;
//const ll mod = 1000000007;
vector<int> g[N];

ll qpow(ll base, ll idx){
	ll res = 1;
	while(idx){
		if(idx & 1) res = res * base % mod;
		base = base * base % mod;
		idx >>= 1;
	}
	return res;
}


void solve() {
	int n; 
	cin >> n;
	for(int i = 1; i <= n; i++) g[i].clear();

	for(int i = 1; i < n; i++){
		int u, v;
		cin >> u >> v;
		g[u].push_back(v);
		g[v].push_back(u);
	}

	vector<int> fa(n + 1), order(1, 1);
	fa[1] = -1;


	queue<int> q;
	q.push(1);

	while(!q.empty()){
		int u = q.front();
		q.pop();
		for(auto v : g[u]){
			if(fa[u] == v) continue;
			fa[v] = u;
			order.push_back(v);
			q.push(v);
		}
	}


	vector<ll> sz(n + 1, 1), sum(n + 1);

	// 从下向上遍历树
	for(int i = n - 1; i >= 0; i--){
		int u = order[i];

		for(int v : g[u]){
			if(v == fa[u]) continue;
			sz[u] += sz[v];
			sum[u] = (sum[u] + sum[v]) % mod;
		}
		sum[u] = (sum[u] + sz[u] * sz[u]) % mod;
	}

	ll ans = 0;

	for(int u = 1; u <= n; u++){
		ll s = sz[u] % mod;
		ll s2 = s * s % mod;

		if(u != 1){
			ll t = (n - sz[u]) % mod;
			ll t2 = t * t % mod;

			ans = (ans + s2 * t2) % mod;

			ll inner = (sum[u] - s2 + mod) % mod;
			ans = (ans + 2 * inner % mod * t2) % mod;
		}

		ll pre = 0;

		// 不同分支
		for(int v : g[u]){
			if(v == fa[u]) continue;

			ans = (ans + 2 * pre % mod * sum[v]) % mod;
			pre = (pre + sum[v]) % mod;
		}
	}

	ll paths = 1ll * n * (n - 1) / 2 % mod;
	ll den = paths * paths % mod;

	cout << ans * qpow(den, mod - 2) % mod << "\n";
}





int main() {
	ios::sync_with_stdio(0);
	cin.tie(0), cout.tie(0);
//	init();
	ll T = 1;
	cin >> T;
	while (T--) solve();
	return 0;
}

