ll merge_sort(int l, int r) {
	if (l >= r) return 0;

	int mid = (l + r) / 2;

	ll ans = 0;

	ans += merge_sort(l, mid);
	ans += merge_sort(mid + 1, r);

	int i = l, j = mid + 1, k = 0;

