#include <bits/stdc++.h>
using namespace std;
const int N = 2e5 + 10;
typedef long long ll;


void solve(){
    ll n, k;
    cin >> n >> k;


    vector<ll>  a(n + 1);

    ll sum = k;
    for(int i = 1; i <= n; i++) cin >> a[i], sum += a[i];

    sort(a.begin() + 1, a.end());

    ll l = 0, r = sum;

    auto check = [&](ll x) -> bool {
        ll b = x / (n - 1);
        ll r = x % (n - 1);

        // 只有一轮
        if(b == 0){
            ll cnt = 0;
            for(int i = 1; i <= n; i++) cnt += (a[i] > 0);
            return cnt + k >= x;
        }

        //lim：每首歌至少播放多少次
        ll lim = (b + (r > 0)) / 2;
        ll kk = k;

        //补足最低要求
        for(int i = 1; i <= n; i++){
            kk -= max(0LL, lim - a[i]);
            if(kk < 0) return false;
        }

        ll cnt = 0, need = 0, extra = 0;

        for(int i = 1; i <= n; i++){
            //补足后的数量
            ll v = max(a[i], lim);

            //在完整组播放的次数
            cnt += min(v, b);
            //需要补足的数量
            need += max(0LL, b - v);
            //如果有多余的数量，进入新一轮
            extra += (v > b);
        }

        //能补足的数量
        ll t = min(kk, need);
        cnt += t; kk -= t;

        if(r > 0) cnt += min(r - 1, extra + kk);

        return cnt >= x;
    };

    while(l < r){
        ll mid = (l + r + 1) / 2;

        if(check(mid)) l = mid;
        else r = mid - 1;
    }
    cout << l << "\n";
}

int main(){
    ios::sync_with_stdio(0);
    cin.tie(0), cout.tie(0);
    int T = 1; 
    cin >> T;
    while(T--) solve();
    return 0;
}
