树形 Hook Length 公式（Tree Hook-Length Formula），也可以理解为有根森林的拓扑序计数公式。
1. 公式
对于一棵有 \(n\) 个节点的有根树，如果要求：

每个父节点必须在所有子节点之前出现，那么合法排列数为：
\[
\boxed{ans=\frac{n!}{\prod_{u=1}^{n}siz[u]}}
\]

其中 \(siz[u]\) 是以 \(u\) 为根的子树节点数（包含自己）。

如果要求所有子节点必须在父节点之前，公式也完全一样。

对于有根森林，同样成立，\(n\) 是所有连通块的节点总数。


######  线性 O(n) 预处理连续数的模逆元

```cpp
#include <bits/stdc++.h>
using namespace std;
const int N = 2e5 + 10;
typedef long long ll;
const ll mod = 998244353;

ll fac[N], inv[N];


void init (){
    fac[0] = 1;
    for(int i = 1; i < N; i++) fac[i] = fac[i - 1] * i % mod;

    // 线性 O(n) 预处理模逆元，也可以不预处理，直接用qpow把最后的分母乘积一下算出来
    inv[1] = 1;
    for (int i = 2; i < N; i++) inv[i] = (mod - mod / i) * inv[mod % i] % mod;
}

void solve(){
    int n;
    cin >> n;

    vector<int> fa(n + 1), a(n + 1), b(n + 1), sz(n + 1, 1);

    for(int i = 2; i <= n; i++) cin >> fa[i];
    for(int i = 1; i <= n; i++) cin >> a[i];
    for(int i = 1; i <= n; i++) cin >> b[i];

    for(int i = n; i >= 2; i--){
        int p = fa[i];

        if(b[i] > a[p] || a[i] > b[p]) sz[p] += sz[i];
    }

    ll ans = fac[n];
    for(int i = 1; i <= n; i++) ans = ans * inv[sz[i]] % mod;
    cout << ans << "\n";
}

int main(){
    ios::sync_with_stdio(0);
    cin.tie(0), cout.tie(0);
    init();
    int T = 1; 
    cin >> T;
    while(T--) solve();
    return 0;
}
