###### 并查集缩点模板

```cpp
#include <bits/stdc++.h>
using namespace std;
const int N = 3e5 + 10;
typedef long long ll;
const ll mod = 998244353;

int fa[N], sz[N];
int dp[N];
vector<int> g[N];
vector<pair<int, int>> order;

void init(int n){
    for(int i = 1; i <= n; i++) fa[i] = i, sz[i] = 1;
}

int find(int x) {
    return fa[x] == x ? x : fa[x] = find(fa[x]);
}

void merge(int x, int y){
    x = find(x), y = find(y);
    if(x == y) return;
    if(sz[x] < sz[y]) swap(x, y);

    fa[y] = x;
    sz[x] += sz[y];
}


void solve(){
    int n, m;

    cin >> n >> m;
    init(n);
    vector<int> a(n + 1);
    vector<pair<int, int> > edge;

    for(int i = 1; i <= n; i++) cin >> a[i];

    for(int i = 0; i < m; i++){
        int u, v; 
        cin >> u >> v;
        edge.push_back({u, v});

        if(a[u] == a[v]) merge(u, v);
    }

    //缩点之后建图

    for(auto [u, v]: edge){
        u = find(u), v = find(v);

        if(u == v) continue;

        if(a[u] > a[v]) swap(u, v);
        // 有向边
        g[u].push_back(v);
    }

    //建立枚举顺序
    for(int i = 1; i <= n; i++){
        if(find(i) == i) order.push_back({a[i], i});
    }
    sort(order.begin(), order.end());

    //要求起点从1开始
    dp[find(1)] = 1;

    for(auto [x, u] : order){

        if(dp[u] == 0) continue;

        for(auto v: g[u]){
            dp[v] = max(dp[v], dp[u] + 1);
        }
    }
    cout << dp[find(n)] << '\n';
}

int main(){
    ios::sync_with_stdio(0);
    cin.tie(0), cout.tie(0);
    int T = 1; 
    // cin >> T;
    while(T--) solve();
    return 0;
}
