对于字典序，考虑比较的量有：
- 首个出现的数值
- 首个出现数值维持的长度
- 第二个出现的数值
- 第二个数值出现的长度

……

- 可以考虑把第二个之后的情况压缩进一个rank，这样可以从后往前一边代入一边做。
- 由于有数值和数值维持的长度两个东西需要比较，可以先按照数值分组，`{组内按照维持长度、第二个出现的数值、该数值在自己组内的rank}`组成三元组，从后往前求解rank；
- 最后，从第一组当中找到rank最小（也就是组内rank为0）的数，就是所需要求的起始位置。

```cpp
#include <bits/stdc++.h>
using namespace std;
const int N = 5e5 + 10;
typedef long long ll;
const ll mod = 998244353;

int dist[N], a[2 * N], r[N], pre[N], nxt[N];

void solve(){
    int n;
    cin >> n;

    for(int i = 1;  i <= n; i++) cin >> a[i], a[i + n] = a[i];


    vector<int> start;
    stack<int> st;

    for(int i = 2 * n; i >= 1; i--){
        while(!st.empty() && a[st.top()] <= a[i]) st.pop();

        if(i <= n){
            //注意使模n为n的模数的写法
            if(!st.empty()) dist[i] = st.top() - i, nxt[i] = (st.top() - 1) % n + 1;
            else dist[i] = n, nxt[i] = i;
        }
        st.push(i);
    }

    map<int, vector<int> > mp;

    for(int i = 1; i <= n; i++) mp[a[i]].push_back(i), r[i] = 0;

    //排名dp
    for(auto it = mp.rbegin(); it != mp.rend(); it++){
        //从任何一个最大值位置出发，得到的前缀最大值序列都完全相同，可以跳过
        if(it == mp.rbegin()) continue;

        vector<array<int, 4> > v;

        //对于每个开头相同的组：先比较维持时间，再比较下个位置的大小、下个位置在其组内的排序
        for(int i : it->second) v.push_back({-dist[i], a[nxt[i]], r[nxt[i]], i});

        sort(v.begin(), v.end());

        int rk = 0;

        //对每个组求解组内排名
        for(int j = 0; j < v.size(); j++){
            //注意这里包含了r的排序，所以是利用了之前求解下一个位置的r的信息在求组内排序
            if(j && (v[j][0] != v[j-1][0] || v[j][1] != v[j-1][1] || v[j][2] != v[j-1][2])) rk++;

            r[v[j][3]] = rk;
        }
    }

    int ans = 0;
    //最小值组中找答案
    for(int i : mp.begin()->second){
        if(r[i] == 0) {ans = i; break;}
    }

    int mx = a[ans];
    for(int i = ans; i < ans + n; i++){
        mx = max(mx, a[i]);
        cout << mx << " ";
    }
    cout << "\n";
}

int main(){
    ios::sync_with_stdio(0);
    cin.tie(0), cout.tie(0);
    int T = 1; 
    cin >> T;
    while(T--) solve();
    return 0;
}
