- 状态设计：当前牌是否被删除取决于骰子的点数和当前牌的位置，记录为一个状态，那么由牌的总数从小到大推出每个状态即可
- 容易计算，每次删去的牌数为 `nn = n - n / 6 - (x <= n % 6);`；
- 而k的位置变动就是它减去它前面被删掉的牌，也就是 `(k < x ? 0 : (k - x) / 6 + 1)`
- 注意使用dfs时，`dp[n][k]`不会访问全部的n状态，因为 $ n > 6 $ 时，只可能删去` n / 6 `或` n / 6  + 1`张牌，dfs进入的状态非常少，只有枚举位置 `k` 时是 $ O(n) $ 的，整体时间复杂度仍然近似线性
- 从`dp[1][1] = 1`开始，合并子状态，每个位置的牌的幸存概率是骰子掷出1-6时，将会转移到的位置的概率之和。
- 注意讨论剩余牌数小于6的情况，只考虑骰子掷出的点数小于6的情况即可 `int m = min(n, 6);`，骰子掷出的点数小于k则k前有一张牌被拿走，否则不变。

###### 二维数组的稀疏访问方法：`vector<int> dp[N]; dp[n].resize(n + 1);`



```cpp
#include <bits/stdc++.h>
using namespace std;
const int N = 5e5 + 10;
typedef long long ll;
const ll mod = 998244353;


vector<int> dp[N];
int vis[N];
ll inv[7];

ll qpow(ll a, ll b){
    ll res = 1;
    while(b){
        if(b & 1) res = res * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}

void dfs(int n){
    if(vis[n]) return;

    vis[n] = 1;

    if(n == 1) {dp[n] = {0, 1}; return;}

    int m = min(n, 6);

    for(int x = 1; x <= m; x++){
        //本轮过后剩余牌的数量，先计算出来。
        //实际只会访问很少的nn，时间复杂度是线性的
        int nn = n - n / 6 - (x <= n % 6);
        dfs(nn);
    }

    //二维数组只开本轮所需要的状态数
    dp[n].resize(n + 1);

    for(int k = 1; k <= n; k++){
        ll sum = 0;

        //计算每个牌每种点数的剩余概率
        for(int x = 1; x <= m; x++){
            //当前牌无法幸存
            if(k >= x && (k - x) % 6 == 0) continue;

            int nn = n - n / 6 - (x <= n % 6);
            //该牌前面会被拿走的牌
            int cnt = (k < x ? 0 : (k - x) / 6 + 1);
            //计算本轮过后当前牌的排位
            int rk = k - cnt;

            //从下一轮的此种状态中中幸存的概率
            sum += dp[nn][rk];
        }

        dp[n][k] = sum % mod * inv[m] % mod;
    }
}




void solve(){
    int n; 
    cin >> n;
    for(int i = 1; i <= 6; i++) inv[i] = qpow(i, mod - 2);

    dfs(n);
    for(int i = 1; i <= n; i++) cout << dp[n][i] << "\n";

}

int main(){
    ios::sync_with_stdio(0);
    cin.tie(0), cout.tie(0);
    int T = 1; 
    // cin >> T;
    while(T--) solve();
    return 0;
}
```
